exercises.starterCode:
function compterParAuteur(livres) {
  // Retourner un objet { idAuteur: nombre de livres }
}

exercises.solution:
function compterParAuteur(livres) {
  const acc = {};
  for (const l of livres) {
    acc[l.idAuteur] = (acc[l.idAuteur] || 0) + 1;
  }
  return acc;
}

